action.command:
python3 -I -c "import os, pathlib, xml.etree.ElementTree as ET, json; root=pathlib.Path(os.environ['LABVIEW_ENVIRONMENT']); targets=[]
for repo in ('actor-framework','pylavi'):
    for p in (root/repo).rglob('*'):
        if p.suffix.lower() in ('.lvproj','.vipb','.vipc'):
            targets.append((repo,p))
for repo,p in sorted(targets, key=lambda x:(x[0], str(x[1]))):
    rel=str(p.relative_to(root/repo))
    print(f'=== {repo}/{rel}')
    try:
        t=ET.parse(p)
        r=t.getroot()
    except Exception as e:
        print('parse_error', type(e).__name__, str(e))
        continue
    print('root', r.tag, dict(sorted(r.attrib.items())))
    hits=[]
    for e in r.iter():
        txt=(e.text or '').strip()
        attrs={k:v for k,v in e.attrib.items() if any(k2 in k.lower() for k2 in ('name','id','version','dependency','path','url','package'))}
        tag=e.tag.lower()
        if ('depend' in tag) or ('package' in tag) or ('require' in tag) or ('version' in tag) or attrs:
            if txt or attrs or tag.endswith('item'):
                hits.append({'tag':e.tag,'attrs':attrs,'text':txt[:180]})
    print('hits', len(hits))
    for h in hits[:80]:
        print(json.dumps(h, ensure_ascii=False))
"

